"""DMGHG PC Local HTTP Bridge Service.

Provides a loopback-only (127.0.0.1) HTTP service bridging HikerView rules
to the locally installed DMGHG desktop application via its native electron_bridge.dll.
Does NOT modify application files, does NOT read user sessions or accounts.
"""

import argparse
import ctypes
from http.server import HTTPServer, BaseHTTPRequestHandler
import json
import os
from pathlib import Path
import socket
from socketserver import ThreadingMixIn
import sys
import tempfile
import threading
import urllib.parse


class Bridge:
    """Wrapper around electron_bridge.dll exporting a safe read-only RPC interface."""

    READ_COMMANDS = {
        "app.ping",
        "catalog.get_channels",
        "catalog.get_banners",
        "catalog.get_video_list",
        "catalog.search_video",
        "catalog.get_video_key",
        "catalog.get_video_detail",
        "catalog.get_channel_detail",
        "video.play",
    }

    def __init__(self, app_dir):
        if os.name != "nt":
            raise RuntimeError("The installed bridge requires Windows x64 Python")
        self.app_dir = Path(app_dir).resolve(strict=True)
        self.dll_path = self.app_dir / "electron_bridge.dll"
        if not self.dll_path.is_file():
            raise RuntimeError(f"electron_bridge.dll is missing from {self.app_dir}")
        self.state_root = Path(tempfile.mkdtemp(prefix="dmghg-bridge-"))
        os.environ["DMGHG_TEST_DATA_ROOT"] = str(self.state_root)
        os.environ["RUST_LOG"] = "error"
        self.dll = ctypes.CDLL(str(self.dll_path))
        self.dll.dmghg_service_new.argtypes = [ctypes.c_char_p, ctypes.c_char_p]
        self.dll.dmghg_service_new.restype = ctypes.c_void_p
        self.dll.dmghg_service_handle_command_json.argtypes = [ctypes.c_void_p, ctypes.c_char_p]
        self.dll.dmghg_service_handle_command_json.restype = ctypes.c_void_p
        self.dll.dmghg_string_free.argtypes = [ctypes.c_void_p]
        self.dll.dmghg_service_free.argtypes = [ctypes.c_void_p]
        self.lock = threading.RLock()
        self.version = installed_version(self.app_dir / "dmghg.exe")
        self.handle = self.dll.dmghg_service_new(b"dmghg-flutter", self.version.encode("ascii"))
        if not self.handle:
            raise RuntimeError("The installed bridge could not initialize")

    def call(self, command, payload=None):
        if command not in self.READ_COMMANDS:
            raise ValueError(f"Command '{command}' is outside the inspection allowlist")
        request = {
            "request_id": "bridge-rpc",
            "protocol_version": 1,
            "command": command,
            "payload": payload or {},
        }
        with self.lock:
            prev = os.getcwd()
            try:
                # The installed Lua resolver loads resources/lua relative to Cwd.
                os.chdir(str(self.app_dir))
                ptr = self.dll.dmghg_service_handle_command_json(
                    self.handle, json.dumps(request, ensure_ascii=False).encode("utf-8")
                )
                if not ptr:
                    raise RuntimeError("Bridge returned a null response")
                try:
                    response = json.loads(ctypes.string_at(ptr).decode("utf-8"))
                finally:
                    self.dll.dmghg_string_free(ptr)
            finally:
                os.chdir(prev)
        if response.get("ok") is not True:
            error = response.get("error", {})
            raise RuntimeError(f"{error.get('code', 'unknown')}: {error.get('message', 'operation failed')}")
        return response.get("data")

    def close(self):
        with self.lock:
            if self.handle:
                self.dll.dmghg_service_free(self.handle)
                self.handle = None


def installed_version(exe):
    """Read PE version metadata from dmghg.exe."""
    version = ctypes.windll.version
    size = version.GetFileVersionInfoSizeW(str(exe), None)
    if not size:
        raise RuntimeError("Cannot read the installed application's version metadata")
    buffer = ctypes.create_string_buffer(size)
    if not version.GetFileVersionInfoW(str(exe), 0, size, buffer):
        raise RuntimeError("Cannot read application version info")
    info = ctypes.c_void_p()
    length = ctypes.c_uint()
    if not version.VerQueryValueW(buffer, "\\", ctypes.byref(info), ctypes.byref(length)):
        raise RuntimeError("Application version structure is missing")
    fields = ctypes.cast(info, ctypes.POINTER(ctypes.c_uint32))
    if fields[0] != 0xFEEF04BD or length.value < 52:
        raise RuntimeError("Application version structure is invalid")
    return f"{fields[2] >> 16}.{fields[2] & 65535}.{fields[3] >> 16}"


class ThreadingHTTPServer(ThreadingMixIn, HTTPServer):
    daemon_threads = True
    allow_reuse_address = True


class BridgeHandler(BaseHTTPRequestHandler):
    timeout = 5.0
    protocol_version = "HTTP/1.1"

    def setup(self):
        self.request.settimeout(self.timeout)
        super().setup()

    def handle(self):
        try:
            super().handle()
        except (socket.timeout, TimeoutError):
            try:
                self.send_error(408, "Request Timeout")
            except Exception:
                pass
        except (ConnectionResetError, BrokenPipeError):
            pass

    def _send_json(self, status, payload):
        data = json.dumps(payload, ensure_ascii=False).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(data)))
        self.send_header("Connection", "close")
        self.end_headers()
        self.wfile.write(data)

    def do_GET(self):
        parsed = urllib.parse.urlparse(self.path)
        path = parsed.path
        params = urllib.parse.parse_qs(parsed.query)

        try:
            if path == "/ping":
                self._send_json(200, {
                    "ok": True,
                    "version": self.server.bridge.version,
                    "service": "dmghg-bridge",
                    "status": "running"
                })
            elif path == "/channels":
                channels = self.server.bridge.call("catalog.get_channels")
                self._send_json(200, {
                    "ok": True,
                    "data": channels,
                    "items": channels
                })
            elif path == "/video_list":
                ch_raw = params.get("channel", ["20"])[0]
                pg_raw = params.get("page", ["1"])[0]
                channel = int(ch_raw) if ch_raw.isdigit() else ch_raw
                page = int(pg_raw) if pg_raw.isdigit() else 1
                result = self.server.bridge.call("catalog.get_video_list", {
                    "channel": channel,
                    "page": page
                })
                self._send_json(200, {"ok": True, "data": result})
            elif path == "/search":
                key = params.get("key", [""])[0]
                pg_raw = params.get("page", ["1"])[0]
                # Notice: catalog.search_video strictly expects string page
                result = self.server.bridge.call("catalog.search_video", {
                    "key": key,
                    "page": str(pg_raw)
                })
                self._send_json(200, {"ok": True, "data": result})
            elif path == "/detail":
                vid = params.get("id", [""])[0]
                result = self.server.bridge.call("catalog.get_video_detail", {
                    "id": str(vid)
                })
                self._send_json(200, {"ok": True, "data": result})
            elif path == "/play":
                vid = params.get("id", [""])[0]
                part = params.get("part", [""])[0]
                play = params.get("play", [""])[0]
                result = self.server.bridge.call("video.play", {
                    "id": str(vid),
                    "part": part,
                    "play": play,
                    "resolve": True
                })
                self._send_json(200, {"ok": True, "data": result})
            else:
                self._send_json(404, {"ok": False, "error": {"code": "not_found", "message": "Unknown path"}})
        except Exception as e:
            self._send_json(500, {"ok": False, "error": {"code": "internal_error", "message": str(e)}})

    def do_POST(self):
        parsed = urllib.parse.urlparse(self.path)
        path = parsed.path

        if path != "/call":
            self._send_json(404, {"ok": False, "error": {"code": "not_found", "message": "Only /call supported"}})
            return

        try:
            length = int(self.headers.get("Content-Length", 0))
            if length <= 0 or length > 1024 * 1024:
                self._send_json(400, {"ok": False, "error": {"code": "bad_request", "message": "Invalid body length"}})
                return

            body = self.rfile.read(length)
            req = json.loads(body.decode("utf-8"))
            command = req.get("command")
            payload = req.get("payload", {})

            if command not in Bridge.READ_COMMANDS:
                self._send_json(403, {
                    "ok": False,
                    "error": {
                        "code": "forbidden_command",
                        "message": f"Command '{command}' is not in inspection allowlist"
                    }
                })
                return

            result = self.server.bridge.call(command, payload)
            self._send_json(200, {"ok": True, "data": result})
        except json.JSONDecodeError:
            self._send_json(400, {"ok": False, "error": {"code": "bad_json", "message": "Malformed JSON payload"}})
        except Exception as e:
            self._send_json(500, {"ok": False, "error": {"code": "call_failed", "message": str(e)}})

    def log_message(self, format, *args):
        # Silent logger to prevent stdout pollution during verification
        pass


def run_server(app_dir, port=18002):
    bridge = Bridge(app_dir)
    server = ThreadingHTTPServer(("127.0.0.1", port), BridgeHandler)
    server.bridge = bridge
    print(f"DMGHG Bridge running on [REDACTED_URL] (PID: {os.getpid()})")
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        server.server_close()
        bridge.close()


def main():
    parser = argparse.ArgumentParser(description="DMGHG Local Headless HTTP Bridge")
    parser.add_argument("--app-dir", required=True, help="Directory containing dmghg.exe and electron_bridge.dll")
    parser.add_argument("--port", type=int, default=18002, help="Loopback port to bind (default: 18002)")
    parser.add_argument("--host", default="127.0.0.1", help="Must be 127.0.0.1")
    args = parser.parse_args()

    if args.host != "127.0.0.1":
        sys.stderr.write("Security Error: Only loopback 127.0.0.1 is permitted\n")
        sys.exit(1)

    run_server(args.app_dir, args.port)


if __name__ == "__main__":
    main()

